"use client";
import Link from 'next/link';
import { ArrowRightIcon } from '@heroicons/react/24/outline';

export default function Home() {
  return (
    <div className="relative min-h-screen bg-gray-100 p-6">
      <header className="text-center mb-12">
        <h1 className="text-4xl font-bold text-blue-600">Welcome to Our Loan Service</h1>
        <p className="mt-4 text-lg text-gray-700">
          Get the financial support you need with flexible loan options. Apply today!
        </p>
      </header>

      {/* Apply Loan Button on the top-right */}
      <Link href="/loan-application">
        <a className="absolute top-6 right-6 flex items-center gap-2 rounded-lg bg-blue-600 px-6 py-3 text-white shadow-lg hover:bg-blue-500 transition-colors">
          Apply for Loan
          <ArrowRightIcon className="w-5" />
        </a>
      </Link>

      <div className="bg-white shadow-md rounded-lg p-8 w-full max-w-md mt-20">
        <h2 className="text-xl font-semibold text-center text-gray-800">Start Your Application</h2>
        <p className="mt-2 text-gray-600 text-center">Click the button above to apply for a loan.</p>
      </div>

      <footer className="mt-12 text-center text-sm text-gray-500">
        <p>&copy; 2025 Loan Services Inc. All rights reserved.</p>
      </footer>
    </div>
  );
}
